import json
import os
import sys
from decimal import Decimal

def format_amount(val):
    if val is None:
        return None
    return str(Decimal(str(val)))

def format_date(val):
    if val is None:
        return None
    return str(val).split(" ")[0]

def get_field(record, fact_name, rule_id):
    if rule_id == "usa.period_3y":
        pop = record.get("period_of_performance") or {}
        if fact_name == "performance start":
            return format_date(pop.get("start_date"))
        elif fact_name == "performance end":
            return format_date(pop.get("end_date"))
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            return format_amount(record.get("total_obligation"))
        elif fact_name == "potential value":
            return format_amount(record.get("base_and_all_options"))
    return None

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    doc_name = os.path.splitext(os.path.basename(awards_path))[0]

    with open(awards_path) as f:
        awards = json.load(f)

    by_id = {}
    for award in awards:
        gid = award.get("generated_unique_award_id")
        if gid is not None:
            by_id.setdefault(gid, []).append(award)

    result = {}
    for pair in manifest["pairs"]:
        rule_id, entity = pair.split("::", 1)
        facts = manifest["facts"].get(rule_id, [])
        fact_results = {}
        records = by_id.get(entity, [])
        for fact_name in facts:
            values = []
            for rec in records:
                v = get_field(rec, fact_name, rule_id)
                if v is not None:
                    values.append(v)
            if not values:
                fact_results[fact_name] = "ABSENT"
            elif len(set(values)) == 1:
                fact_results[fact_name] = [values[0], doc_name]
            else:
                fact_results[fact_name] = "CONFLICT"
        result[pair] = fact_results

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

