import json
import os
import sys
from decimal import Decimal

def format_amount(value):
    if value is None:
        return None
    d = Decimal(str(value))
    return str(d.quantize(Decimal('0.01')))

def format_date(value):
    if value is None:
        return None
    s = str(value)
    if ' ' in s:
        return s.split(' ')[0]
    return s

def get_field_value(award, rule_id, fact_name):
    if rule_id == "usa.period_3y":
        pop = award.get("period_of_performance") or {}
        if fact_name == "performance start":
            return format_date(pop.get("start_date"))
        elif fact_name == "performance end":
            return format_date(pop.get("end_date"))
    elif rule_id == "usa.obligated_95":
        if fact_name == "amount obligated":
            return format_amount(award.get("total_obligation"))
        elif fact_name == "potential value":
            return format_amount(award.get("base_and_all_options"))
    return None

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts_by_rule = manifest["facts"]

    # Load all JSON files in the packet directory
    documents = {}
    for filename in os.listdir(packet_dir):
        if filename.endswith('.json'):
            doc_name = filename[:-5]
            filepath = os.path.join(packet_dir, filename)
            with open(filepath) as f:
                documents[doc_name] = json.load(f)

    # Index awards by generated_unique_award_id
    awards_by_id = {}
    if "usaspending_awards" in documents:
        awards = documents["usaspending_awards"]
        if isinstance(awards, list):
            for award in awards:
                award_id = award.get("generated_unique_award_id")
                if award_id:
                    awards_by_id.setdefault(award_id, []).append(award)
        elif isinstance(awards, dict):
            award_id = awards.get("generated_unique_award_id")
            if award_id:
                awards_by_id.setdefault(award_id, []).append(awards)

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_by_rule.get(rule_id, [])

        pair_result = {}

        for fact_name in fact_names:
            doc_name = "usaspending_awards"
            matching_records = awards_by_id.get(entity, [])

            if not matching_records:
                pair_result[fact_name] = "ABSENT"
                continue

            values = []
            for record in matching_records:
                val = get_field_value(record, rule_id, fact_name)
                if val is not None:
                    values.append(val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            elif len(set(values)) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [values[0], doc_name]

        result[pair] = pair_result

    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

