import json
import os
import sys
from decimal import Decimal

def main():
    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path) as f:
        manifest = json.load(f)

    pairs = manifest["pairs"]
    facts = manifest["facts"]

    awards_path = os.path.join(packet_dir, "usaspending_awards.json")
    with open(awards_path) as f:
        awards = json.load(f, parse_float=Decimal)

    awards_by_id = {}
    for award in awards:
        uid = award.get("generated_unique_award_id")
        if uid is not None:
            awards_by_id.setdefault(uid, []).append(award)

    rule_fields = {
        "usa.period_3y": {
            "performance start": ("period_of_performance", "start_date"),
            "performance end": ("period_of_performance", "end_date"),
        },
        "usa.obligated_95": {
            "amount obligated": ("total_obligation",),
            "potential value": ("base_and_all_options",),
        },
    }

    doc_name = "usaspending_awards"

    result = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        fact_names = facts.get(rule_id, [])
        matching_awards = awards_by_id.get(entity, [])

        fact_results = {}
        for fact_name in fact_names:
            field_path = rule_fields.get(rule_id, {}).get(fact_name)
            if field_path is None:
                fact_results[fact_name] = "ABSENT"
                continue

            values = []
            for award in matching_awards:
                val = award
                for key in field_path:
                    if isinstance(val, dict):
                        val = val.get(key)
                    else:
                        val = None
                    if val is None:
                        break
                if val is not None:
                    values.append(val)

            if not values:
                fact_results[fact_name] = "ABSENT"
            else:
                first = values[0]
                if isinstance(first, str):
                    normalized = [v[:10] if len(v) > 10 else v for v in values]
                    if len(set(normalized)) > 1:
                        fact_results[fact_name] = "CONFLICT"
                    else:
                        fact_results[fact_name] = [normalized[0], doc_name]
                else:
                    if any(v != first for v in values):
                        fact_results[fact_name] = "CONFLICT"
                    else:
                        fact_results[fact_name] = [str(first), doc_name]

        result[pair] = fact_results

    print(json.dumps(result))

main()
